# PATH P2 (platform plan knowledge-base-plan.md, KB3: the conversion of knowledge-document originals; idp-cmi ADR-0001 D61 to D70; idp-sandbox D25), shared by deploy/compose/e2e.sh and
# tests/kind/full.sh, which `source` it after PATH P1 (it needs p1_sql, p1_metric and p0_s3_keys, which P0 and P1 define). Everything goes through CMI's HTTP API with real Keycloak tokens
# (carol, a member with the role cmi-reader, owns every document of this path in her personal base; alice, cmi-admin, erases carol as a subject at the end), the real system gateway, the
# real ingest sandbox and its converters; the stored text, the jobs and the tickets are looked at in the database. No business document: the test documents are generated by
# deploy/compose/kb3_docs.py from invented words that carry a per-run suffix. Waits are bounded and measured from the clock; the one thing that is arranged is the outage of
# the ingest sandbox in (b), which makes "the previous version stays current while a conversion cannot finish" a state rather than a race.
# What the caller supplies: CMI, `user_token NAME`, `call EXPECTED METHOD URL TOKEN [BODY]`, `field`, L (the directory of generated files), ISSUER, SYSTEM_TENANT, the system gateway's
# audience and URL and the member-side gateway's (P2_SYS_AUD, P2_SYS_URL, P2_EDGE_AUD, P2_EDGE_URL), and the adapters
#   p2_sandbox_stop / p2_sandbox_start   the ingest sandbox stopped; started and answering
#   p2_forged_post                       a forged write ticket posted to the file endpoint from where the ingest sandbox stands: prints the HTTP status
#   p2_reach FROM TARGET                 0 when a TCP connection from FROM (host, workspace, web, eer, ingest-sandbox, cmi, runs) to TARGET (file-endpoint, system-gateway) is made
#   P2_SYSGW_ISOLATED                    1 where the system gateway is unreachable from the member side by the network (kind); compose cannot narrow that and says so
#   P2_NET_WHAT                          one sentence on how the reach checks were made, for the PASS line
set -u
R2="$(openssl rand -hex 3)"; P2_SRC="p2-notes"
p2w() { echo "$1${R2//[0-9]/x}"; }   # a word made of letters only (no digit: no stemming or token split turns it into two)
W_PDF1="$(p2w kestrel)"; W_PDF2="$(p2w plover)"; W_PDF3="$(p2w avocet)"; W_DOCT="$(p2w bittern)"; W_DOCS="$(p2w godwit)"; W_DOCC="$(p2w nuthatch)"
W_PPT1="$(p2w siskin)"; W_PPT2="$(p2w whimbrel)"; W_PPT3="$(p2w sanderling)"; W_XLS="$(p2w curlew)"; W_KEEP="$(p2w dunlin)"; W_DROP="$(p2w knotty)"
W_OLD="$(p2w ruddock)"; W_NEW="$(p2w merlin)"; W_NEWH="$(p2w harrier)"; W_NEWC="$(p2w shrike)"; W_SCAN="$(p2w osprey)"
P2D="$L/p2-docs"; rm -rf "$P2D"; mkdir -p "$P2D"
P2_DOCS=()
p2_bad() { echo "FAIL: PATH P2 $*" >&2; exit 1; }
P2_TOK_AT=0
p2_fresh() { local now; now=$(date +%s); (( now - P2_TOK_AT > 240 )) && { CAROL="$(user_token carol)"; P2_TOK_AT=$now; }; return 0; }   # a token lives 10 minutes
p2_now_ms() { echo $(( $(date +%s%N) / 1000000 )); }
p2_q() { python3 -c "import json,sys; print(json.dumps({'query':sys.argv[1],'purpose':'assist','budget':{'maxItems':8}}))" "$1"; }
# p2_loc WORD: the locator (JSON) of the first item of carol's resolve whose text has WORD, or "none"
p2_loc() { p2_fresh; call 200 POST "$CMI/v1/context/resolve" "$CAROL" "$(p2_q "$1")" | python3 -c "
import json,sys
for it in json.load(sys.stdin)['package']['items']:
    if sys.argv[1] in json.dumps(it, ensure_ascii=False): print(json.dumps(it.get('locator') or {}, ensure_ascii=False, sort_keys=True)); break
else: print('none')" "$1"; }
# p2_new NAME TITLE TEXT: a version of kb://me/NAME with text the writer supplies (a placeholder, or the text of an earlier version); prints its id
p2_new() { local id; p2_fresh; id="$(call 201 POST "$CMI/v1/knowledge/documents" "$CAROL" "$(python3 -c "import json,sys; print(json.dumps({'source':sys.argv[1],'uri':'kb://me/'+sys.argv[2],'title':sys.argv[3],'text':sys.argv[4]}))" "$P2_SRC" "$1" "$2" "$3")" | field "['documentId']")"; echo "$id" >> "$P2D/docs.txt"; echo "$id"; }   # p2_new runs in a subshell: the ids of every document of this path are kept in a file
p2_put() { local code; p2_fresh; code="$(curl -s --noproxy '*' -o "$P2D/put.out" -w '%{http_code}' -X PUT "$CMI/v1/knowledge/documents/$1/original" -H "Authorization: Bearer $CAROL" -H "Content-Type: $2" --data-binary @"$3")"; [[ "$code" == 200 ]] || p2_bad "the upload of $3 was HTTP $code: $(head -c 300 "$P2D/put.out")"; }
# p2_state ID: "status|ingest state|attempts|error|next|notice" ("-" where absent; next is "next" when a retry is scheduled)
p2_state() { p2_fresh; call 200 GET "$CMI/v1/knowledge/documents/$1" "$CAROL" | python3 -c "
import json,sys
d=json.load(sys.stdin); i=d.get('ingest') or {}
print('|'.join([d['status'], i.get('state','-'), str(i.get('attempts',0)), i.get('error','-'), 'next' if i.get('nextAttemptAt') else '-', (i.get('notice') or '-').replace('\n',' / ')]))"; }
# p2_wait ID SECONDS: until the conversion has ended (succeeded, truncated, or failed with no retry scheduled); sets P2_ST (the p2_state line) and P2_WAITED (seconds, to a tenth)
p2_wait() { local t0 st; t0=$(p2_now_ms)
  while :; do
    st="$(p2_state "$1")"; IFS='|' read -r _ s2 _ _ nx _ <<<"$st"
    if [[ "$s2" == succeeded || "$s2" == truncated || ( "$s2" == failed && "$nx" == - ) ]]; then break; fi
    (( $(p2_now_ms) - t0 > $2 * 1000 )) && p2_bad "$1: after $2 s the conversion is '$st'"
    sleep 1
  done
  P2_ST="$st"; P2_WAITED="$(python3 -c "print(round(($(p2_now_ms) - $t0) / 1000, 1))")"; }
p2_hasloc() { python3 -c "
import json,sys
loc=json.loads(sys.argv[1]); want=json.loads(sys.argv[2])
sys.exit(0 if all(loc.get(k)==v for k,v in want.items()) else 1)" "$1" "$2"; }
curl -s --noproxy '*' -o /dev/null -X POST "$CMI/api/v1/sources" -H "Authorization: Bearer $(user_token alice)" -H 'Content-Type: application/json' --data '{"name":"'"$P2_SRC"'","displayName":"P2 members notes","kind":"user","trust":"informational"}'   # 201, or 409 on a rerun (the source stays)
CAROL="$(user_token carol)"; P2_TOK_AT=$(date +%s)
CAROL_ID="$(python3 -c "import base64,json,sys; t=sys.argv[1].split('.')[1]; print(json.loads(base64.urlsafe_b64decode(t+'='*(-len(t)%4)))['sub'])" "$CAROL")"
MEDIA_PDF=application/pdf MEDIA_DOCX=application/vnd.openxmlformats-officedocument.wordprocessingml.document
MEDIA_PPTX=application/vnd.openxmlformats-officedocument.presentationml.presentation MEDIA_XLSX=application/vnd.openxmlformats-officedocument.spreadsheetml.sheet
CONV0="$(p1_metric idp_cmi_conversions_total outcome=succeeded)"

# (a) one of each type, uploaded as originals: each ends succeeded, and a word of each is found with the locator of its kind
python3 -I deploy/compose/kb3_docs.py pdf3 "$P2D/rota.pdf" "$W_PDF1" "$W_PDF2" "$W_PDF3"
python3 -I deploy/compose/kb3_docs.py docx "$P2D/handbook.docx" "$W_DOCT" "$W_DOCS" "$W_DOCC"
python3 -I deploy/compose/kb3_docs.py pptx "$P2D/review.pptx" "$W_PPT1" "$W_PPT2" "$W_PPT3"
python3 -I deploy/compose/kb3_docs.py xlsx "$P2D/totals.xlsx" "$W_XLS"
P2_A=""
P2_PDF="$(p2_new "rota-$R2.pdf" "Dock rota $R2" "Dock rota $R2 (text to come from the original)")"
P2_DOCX="$(p2_new "handbook-$R2.docx" "Travel handbook $R2" "Travel handbook $R2 (text to come from the original)")"
P2_PPTX="$(p2_new "review-$R2.pptx" "Depot review $R2" "Depot review $R2 (text to come from the original)")"
P2_XLSX="$(p2_new "totals-$R2.xlsx" "Totals $R2" "Totals $R2 (text to come from the original)")"
# before the original, a version with only its placeholder is active; storing a PDF or Office original makes it pending while it is converted (D64)
p2_put "$P2_PDF" "$MEDIA_PDF" "$P2D/rota.pdf"
[[ "$(p2_state "$P2_PDF" | cut -d'|' -f1)" == pending ]] || p2_bad "(a): the version of the PDF is '$(p2_state "$P2_PDF")' right after its original was stored, not pending (D64)"
p2_wait "$P2_PDF" 240; [[ "$P2_ST" == active\|succeeded\|* ]] || p2_bad "(a): the PDF ended '$P2_ST'"; T_PDF="$P2_WAITED"
LOC="$(p2_loc "$W_PDF2")"; p2_hasloc "$LOC" '{"page": 2}' || p2_bad "(a): the PDF's word of page 2 is located '$LOC'"; P2_A+="PDF 3 pages: page 2 word found at $LOC after $T_PDF s; "
p2_put "$P2_DOCX" "$MEDIA_DOCX" "$P2D/handbook.docx"; p2_wait "$P2_DOCX" 240; [[ "$P2_ST" == active\|succeeded\|* ]] || p2_bad "(a): the DOCX ended '$P2_ST'"; T_DOCX="$P2_WAITED"
LOC="$(p2_loc "$W_DOCC")"; python3 -c "
import json,sys
l=json.loads(sys.argv[1]); h=l.get('headings') or []
sys.exit(0 if h[:2]==['Travel handbook ' + sys.argv[2], 'Lodging ' + sys.argv[3]] and l.get('table') else 1)" "$LOC" "$W_DOCT" "$W_DOCS" || p2_bad "(a): the DOCX's table cell word is located '$LOC' (want the heading path Travel handbook > Lodging and a table)"
P2_A+="DOCX: a table cell found under the heading path $LOC after $T_DOCX s; "
p2_put "$P2_PPTX" "$MEDIA_PPTX" "$P2D/review.pptx"; p2_wait "$P2_PPTX" 240; [[ "$P2_ST" == active\|succeeded\|* ]] || p2_bad "(a): the PPTX ended '$P2_ST'"; T_PPTX="$P2_WAITED"
LOC="$(p2_loc "$W_PPT2")"; p2_hasloc "$LOC" '{"slide": 2}' || p2_bad "(a): the PPTX's word of slide 2 is located '$LOC'"; P2_A+="PPTX: slide 2 word found at $LOC after $T_PPTX s; "
p2_put "$P2_XLSX" "$MEDIA_XLSX" "$P2D/totals.xlsx"; p2_wait "$P2_XLSX" 240; [[ "$P2_ST" == active\|succeeded\|* ]] || p2_bad "(a): the XLSX ended '$P2_ST'"; T_XLSX="$P2_WAITED"
LOC="$(p2_loc "$W_XLS")"; python3 -c "
import json,re,sys
l=json.loads(sys.argv[1]); m=re.fullmatch(r'[A-Z]+(\d+):[A-Z]+(\d+)', l.get('range',''))
sys.exit(0 if l.get('sheet')=='Totals' and m and int(m.group(1)) <= 7 <= int(m.group(2)) else 1)" "$LOC" || p2_bad "(a): the XLSX's cell word (row 7) is located '$LOC' (want sheet Totals and a range that has row 7)"
P2_A+="XLSX: the word of cell B7 found at $LOC after $T_XLSX s"
echo "PASS: PATH P2a — four originals uploaded to carol's personal base (CMI -> system gateway -> ingest sandbox -> CMI): each version was pending right after its original was stored and ended active/succeeded; $P2_A"

# (b) a conversion that cannot finish leaves the previous version current; when it finishes the new text is found and the old is not.
# The ingest sandbox is stopped for the first part, so that "during" is a state and not a race with a fast converter: v2 is written (a placeholder), its original stored, the job is
# attempted and cannot be completed. D64: v2 is pending, so v1 stays the current version and v2's text is searched by nobody; a transient failure is retried (D66), or retried by hand
P2_V1="$(p2_new "policy-$R2.docx" "Rota policy $R2" "Rota policy $R2. The previous revision names $W_OLD as the marker of this rule, and it is the current text.")"
[[ "$(p2_loc "$W_OLD")" != none ]] || p2_bad "(b): v1 is not found before the change"
python3 -I deploy/compose/kb3_docs.py docx "$P2D/policy2.docx" "$W_NEWH" "$W_NEW" "$W_NEWC"
p2_sandbox_stop
P2_V2="$(p2_new "policy-$R2.docx" "Rota policy $R2" "Rota policy $R2 (the new revision, its text is being converted)")"
p2_put "$P2_V2" "$MEDIA_DOCX" "$P2D/policy2.docx"
T0=$(p2_now_ms)
for _ in $(seq 1 90); do ST="$(p2_state "$P2_V2")"; IFS='|' read -r _ s2 at _ _ _ <<<"$ST"; [[ "$at" -ge 1 ]] && break; sleep 1; done
[[ "$at" -ge 1 ]] || p2_bad "(b): the conversion was not attempted in 90 s ('$ST')"
IFS='|' read -r s1 s2 _ er _ _ <<<"$ST"
[[ "$s1" == pending && "$s2" != succeeded ]] || p2_bad "(b): during the job v2 is '$ST'"
[[ "$(p2_loc "$W_OLD")" != none ]] || p2_bad "(b): during the job the previous version's text is not found: v1 is not current"
[[ "$(p2_loc "$W_NEW")" == none ]] || p2_bad "(b): during the job the new text is found"
echo "PASS: PATH P2b1 — the ingest sandbox stopped, a new version of kb://me/policy-$R2.docx written and its original stored: after the first attempt ($ST, $(( ($(p2_now_ms) - T0) / 1000 )) s after the upload) the version is pending, the previous version's word is still found and the new text's word is not"
p2_sandbox_start
RETRIED=no
t0=$(p2_now_ms)
while :; do
  ST="$(p2_state "$P2_V2")"; IFS='|' read -r s1 s2 at er nx _ <<<"$ST"
  [[ "$s2" == succeeded ]] && break
  if [[ "$s2" == failed && "$nx" == - ]]; then   # a permanent failure from the outage: the retry is the answer (D63)
    [[ "$RETRIED" == no ]] || p2_bad "(b): the retry ended '$ST' again"
    p2_fresh; call 202 POST "$CMI/v1/knowledge/documents/$P2_V2/ingest" "$CAROL" >/dev/null; RETRIED="yes, by POST /ingest after '$ST'"
  fi
  (( $(p2_now_ms) - t0 > 240000 )) && p2_bad "(b): after the sandbox returned the conversion is '$ST'"
  sleep 1
done
T_B=$(python3 -c "print(round(($(p2_now_ms) - $t0) / 1000, 1))")
IFS='|' read -r s1 _ _ _ _ _ <<<"$ST"
[[ "$s1" == active ]] || p2_bad "(b): v2 is '$ST' after the conversion"
LOC="$(p2_loc "$W_NEWC")"; [[ "$LOC" != none ]] || p2_bad "(b): after the conversion the new text is not found"
python3 -c "
import json,sys
h=json.loads(sys.argv[1]).get('headings') or []
sys.exit(0 if h[:2]==['Travel handbook ' + sys.argv[2], 'Lodging ' + sys.argv[3]] else 1)" "$LOC" "$W_NEWH" "$W_NEW" || p2_bad "(b): the new text's locator is '$LOC'"
[[ "$(p2_loc "$W_OLD")" == none ]] || p2_bad "(b): after the conversion the previous version's word is still found: v2 did not replace v1"
echo "PASS: PATH P2b2 — the sandbox back: v2 became active $T_B s later (retried: $RETRIED), its new text is found at $LOC and the previous version's word is not"

# (c) an XLSX of 10,500 rows: ends truncated, with the notice on the document; the rows kept are searchable, the rows left out are not
python3 -I deploy/compose/kb3_docs.py bigxlsx "$P2D/big.xlsx" 10500 "$W_KEEP" "$W_DROP"
P2_BIG="$(p2_new "big-$R2.xlsx" "Big sheet $R2" "Big sheet $R2 (text to come from the original)")"
p2_put "$P2_BIG" "$MEDIA_XLSX" "$P2D/big.xlsx"; p2_wait "$P2_BIG" 300
IFS='|' read -r s1 s2 _ _ _ notice <<<"$P2_ST"
[[ "$s1" == active && "$s2" == truncated && "$notice" == *10000* && "$notice" == *10500* ]] || p2_bad "(c): the 10,500-row sheet ended '$P2_ST' (want active, truncated, and a notice that names 10000 of 10500)"
LOC="$(p2_loc "$W_KEEP")"; p2_hasloc "$LOC" '{"sheet": "Big"}' || p2_bad "(c): the word of row 3 is located '$LOC'"
[[ "$(p2_loc "$W_DROP")" == none ]] || p2_bad "(c): the word of the last row (10,500), which is past the limit, is found"
echo "PASS: PATH P2c — a sheet of 10,500 rows ended active/truncated after $P2_WAITED s with the notice on the document ('$notice'); the word of row 3 is found at $LOC and the word of row 10,500 is not"

# (d) a scan fails with the no-text code and stays pending; POST .../ingest queues it again; a finished conversion can be run again and ends the same way
python3 -I deploy/compose/kb3_docs.py scan "$P2D/scan.pdf"
P2_SCAN="$(p2_new "scan-$R2.pdf" "Scanned receipt $R2" "Scanned receipt $R2 (text to come from the original)")"
p2_put "$P2_SCAN" "$MEDIA_PDF" "$P2D/scan.pdf"; p2_wait "$P2_SCAN" 240
[[ "$P2_ST" == pending\|failed\|*\|no_text\|-\|* ]] || p2_bad "(d): the scan ended '$P2_ST' (want pending, failed, no_text)"
T_SCAN="$P2_WAITED"; A1="$(echo "$P2_ST" | cut -d'|' -f3)"
RET="$(call 202 POST "$CMI/v1/knowledge/documents/$P2_SCAN/ingest" "$CAROL" | field "['ingest']['state']")"
[[ "$RET" == queued || "$RET" == running ]] || p2_bad "(d): the retry's answer says the conversion is '$RET'"
p2_wait "$P2_SCAN" 240; [[ "$P2_ST" == pending\|failed\|*\|no_text\|-\|* ]] || p2_bad "(d): the retried scan ended '$P2_ST'"
P2_MD="$(p2_new "plain-$R2.md" "Plain note $R2" "A plain markdown note without an original.")"
call 422 POST "$CMI/v1/knowledge/documents/$P2_MD/ingest" "$CAROL" >/dev/null
BEFORE="$(p2_state "$P2_DOCX" | cut -d'|' -f3)"
call 202 POST "$CMI/v1/knowledge/documents/$P2_DOCX/ingest" "$CAROL" >/dev/null
for _ in $(seq 1 240); do ST="$(p2_state "$P2_DOCX")"; IFS='|' read -r s1 s2 at _ _ _ <<<"$ST"; [[ "$s2" == succeeded && "$at" -ge 1 ]] && break; sleep 1; done
[[ "$s2" == succeeded ]] || p2_bad "(d): the finished DOCX conversion run again ended '$ST'"
[[ "$(p2_loc "$W_DOCC")" != none ]] || p2_bad "(d): after running the DOCX conversion again its text is not found"
echo "PASS: PATH P2d — a scanned PDF ended pending/failed/no_text after $T_SCAN s (attempts $A1), its version stays unsearchable; POST .../ingest queued it again (202, '$RET') and it ended failed/no_text again; a markdown document without an original answers 422; the finished DOCX conversion run again through POST .../ingest ended succeeded and its text is still found"

# (e) the tokens: the CMI is served by the system gateway; HOST's delegated token, a member's token and a platform client that is not the CMI are not, and ingest__* is not host-only
HOSTONLY="$(grep -h hostOnlyTools "$L/gateway-system-clients.yaml" "$L/gateway-clients.yaml" 2>/dev/null || true)"
[[ "$HOSTONLY" != *ingest__* ]] || p2_bad "(e): ingest__* is in a hostOnlyTools list: $HOSTONLY (that would lock the CMI out)"
CLIENTS_OF_SYSTEM="$(sed -n 's/^  \([A-Za-z0-9_-]*\):.*/\1/p' "$L/gateway-system-clients.yaml" | tr '\n' ' ')"
EV="$(python3 -I deploy/compose/ingest_check.py "$ISSUER" "$L/tls/ca.crt" "$L/clients.json" "$P2_SYS_AUD" "$P2_SYS_URL" "$P2_EDGE_AUD" "$P2_EDGE_URL" "$SYSTEM_TENANT" "$(python3 -c "import json; print(json.load(open('$L/clients.json'))['ids']['idp-cmi-ingest'])")")" || p2_bad "(e): the token checks failed"
echo "PASS: PATH P2e — $EV; the system gateway's clients file lists only $CLIENTS_OF_SYSTEM and no hostOnlyTools pattern covers ingest__*"

# (f) the network: nothing on the member side reaches the CMI's file endpoint (nor, where the network can say so, the system gateway), and a ticket that is forged is refused
P2_NETBAD=""; P2_NET=""
reach() { # reach FROM TARGET yes|no
  local got=no; p2_reach "$1" "$2" && got=yes
  [[ "$got" == "$3" ]] || P2_NETBAD+=" $1->$2 (reached: $got, want $3)"
  P2_NET+="$1->$2=$got "
}
reach ingest-sandbox file-endpoint yes
for m in host workspace web eer; do reach "$m" file-endpoint no; done
if [[ "${P2_SYSGW_ISOLATED:-0}" == 1 ]]; then reach cmi system-gateway yes; for m in host workspace web eer; do reach "$m" system-gateway no; done; reach runs file-endpoint no; reach runs system-gateway no; fi
[[ -z "$P2_NETBAD" ]] || p2_bad "(f): the network is not as the policies say:$P2_NETBAD"
FORGED="$(p2_forged_post)"
[[ "$FORGED" == 401 || "$FORGED" == 403 ]] || p2_bad "(f): a forged write ticket posted to the file endpoint was answered HTTP $FORGED"
echo "PASS: PATH P2f — $P2_NET_WHAT: $P2_NET; a forged write ticket (a well-formed three-part token signed with another key) posted to the file endpoint from the ingest sandbox's side is refused (HTTP $FORGED)"

# (g) the erasure of carol as a subject removes the extracted text, the conversion jobs and the used tickets of her documents (D69), and the originals
mapfile -t P2_DOCS < "$P2D/docs.txt"
IDS="$(printf "'%s'," "${P2_DOCS[@]}")"; IDS="${IDS%,}"
JOBS0="$(p1_sql "SELECT count(*) FROM knowledge_conversions WHERE document_id IN ($IDS)")"; TICK0="$(p1_sql "SELECT count(*) FROM knowledge_ticket_uses WHERE document_id IN ($IDS)")"
TEXT0="$(p1_sql "SELECT count(*) FROM knowledge_chunks WHERE document_id IN ($IDS) AND content <> '[erased]'")"
OBJ0=0; for d in "${P2_DOCS[@]}"; do OBJ0=$(( OBJ0 + $(p0_s3_keys | grep -c "/$d/" || true) )); done
[[ "$JOBS0" -ge 7 && "$TICK0" -ge 14 && "$TEXT0" -ge 1 && "$OBJ0" -ge 7 ]] || p2_bad "(g): before the erasure there are $JOBS0 jobs, $TICK0 used tickets, $TEXT0 chunks with text and $OBJ0 objects (want at least 7, 14, 1, 7): the test would prove nothing"
ER="$(call 201 POST "$CMI/api/v1/erasures" "$(user_token alice)" '{"subject":"'"$CAROL_ID"'","reason":"P2: the member left"}')"; ER_ID="$(echo "$ER" | field "['erasureId']")"
t0=$(p2_now_ms); ER_STATE=""
for _ in $(seq 1 120); do ER_STATE="$(call 200 GET "$CMI/api/v1/erasures/$ER_ID" "$(user_token alice)" | field "['status']")"; [[ "$ER_STATE" == verified || "$ER_STATE" == failed ]] && break; sleep 1; done
[[ "$ER_STATE" == verified ]] || p2_bad "(g): the erasure $ER_ID is '$ER_STATE', not verified"
T_ER=$(python3 -c "print(round(($(p2_now_ms) - $t0) / 1000, 1))")
# the chunks of the documents of this path were projected (embedded) one event each, the erased ones too: the queue of the projection is drained before the next path, so that what comes after is not
# measured behind it (the 10,000-row sheet alone is about 100 events (255 with wide rows); on a few CPUs that is minutes). Bounded, from the clock.
EV0="$(p1_sql "SELECT count(*) FROM projection_events WHERE processed_at IS NULL")"; t1=$(p2_now_ms)
while [[ "$(p1_sql "SELECT count(*) FROM projection_events WHERE processed_at IS NULL")" != 0 ]]; do (( $(p2_now_ms) - t1 > 1800000 )) && p2_bad "(g): $(p1_sql "SELECT count(*) FROM projection_events WHERE processed_at IS NULL") projection events are still queued 30 minutes after the erasure"; sleep 5; done
T_DRAIN=$(python3 -c "print(round(($(p2_now_ms) - $t1) / 1000, 1))")
JOBS1="$(p1_sql "SELECT count(*) FROM knowledge_conversions WHERE document_id IN ($IDS)")"; TICK1="$(p1_sql "SELECT count(*) FROM knowledge_ticket_uses WHERE document_id IN ($IDS)")"
TEXT1="$(p1_sql "SELECT count(*) FROM knowledge_chunks WHERE document_id IN ($IDS) AND (content <> '[erased]' OR index_text <> '[erased]')")"
LOCS1="$(p1_sql "SELECT count(*) FROM knowledge_chunks WHERE document_id IN ($IDS) AND (sheet <> '' OR cell_range <> '' OR heading_path <> '' OR table_name <> '')")"
OBJ1=0; for d in "${P2_DOCS[@]}"; do OBJ1=$(( OBJ1 + $(p0_s3_keys | grep -c "/$d/" || true) )); done
